CREATE TABLE IF NOT EXISTS support_tickets (id bigserial PRIMARY KEY, ticket_reference varchar(30) NOT NULL UNIQUE, customer_number varchar(30) NOT NULL, request_type varchar(20) NOT NULL, status varchar(20) NOT NULL, priority varchar(10) NOT NULL, subject varchar(150) NOT NULL, description varchar(2000) NOT NULL, assigned_officer varchar(30), resolution varchar(2000), created_at timestamp NOT NULL, updated_at timestamp NOT NULL); CREATE INDEX IF NOT EXISTS idx_support_customer ON support_tickets(customer_number); CREATE INDEX IF NOT EXISTS idx_support_status ON support_tickets(status);
